/**
 * Mailwerk client for the `glassyui` project.
 *
 * Generated by `mailwerk init` from Mailwerk 1.2.0 — do not edit by hand.
 * Regenerate with:
 *
 *     mailwerk init --project glassyui --path src/lib/mailwerk.ts --update
 *
 * Dependency-free on purpose: one file, `fetch`, two environment variables.
 *
 *     MAILWERK_URL=https://api.mailwerk.io
 *     MAILWERK_API_KEY=…            # this project's key, from 1Password
 *
 * This product can only ever see its own project: the key resolves to one
 * project inside Mailwerk, and no cross-project read exists in the API.
 */

export const MAILWERK_PROJECT = 'glassyui';

export const MAILWERK_CLIENT_VERSION = '1.2.0';

export class MailwerkError extends Error {
  readonly code: string;
  readonly status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = 'MailwerkError';
    this.code = code;
    this.status = status;
  }
}

export interface MailwerkOptions {
  url?: string;
  apiKey?: string;
  fetch?: typeof fetch;
  /** Whole request, including the body. No automatic retries on timeout. */
  timeoutMs?: number;
}

/** Only a positive idle_retention state permits a new legitimate owned
 * request to rotate its persisted opaque pointer. Never rotate on an error,
 * missing status or explicit erasure; delayed work keeps the original ID.
 */
export function contactLifecycle(
  externalId: string,
  options?: MailwerkOptions,
): Promise<{ state: 'missing' | 'active' | 'idle_retention' | 'explicit_erasure' }> {
  return call(
    'GET',
    `/v1/contacts/${encodeURIComponent(externalId)}/lifecycle`,
    undefined,
    options,
  );
}

export interface PersonalBriefSettings {
  enabled: boolean;
  held: boolean;
  cadence: 'daily' | 'weekly' | null;
  timeZone: string | null;
  refreshSteam: boolean;
  confirmed: boolean;
  hasDeliveryAddress: boolean;
}

export function personalBriefGet(
  externalId: string,
  options?: MailwerkOptions,
): Promise<PersonalBriefSettings> {
  return call('GET', '/v1/briefs?externalId=' + encodeURIComponent(externalId), undefined, options);
}

export function personalBriefConfigure(
  input: {
    externalId: string;
    email?: string;
    sourceSubject: string;
    enabled: boolean;
    cadence: 'daily' | 'weekly';
    timeZone: string;
    refreshSteam: boolean;
  },
  options?: MailwerkOptions,
): Promise<PersonalBriefSettings> {
  return call('POST', '/v1/briefs/configure', input, options);
}

function settings(options: MailwerkOptions = {}) {
  const url = (options.url ?? process.env.MAILWERK_URL ?? 'https://api.mailwerk.io').replace(
    /\/+$/,
    '',
  );

  const key = options.apiKey ?? process.env.MAILWERK_API_KEY ?? '';

  if (!key) throw new MailwerkError('unauthorized', 'MAILWERK_API_KEY is not set', 401);

  return { url, key, fetch: options.fetch ?? fetch };
}

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

type JsonRequest = { [key: string]: JsonValue | undefined };

async function call<T extends object>(
  method: 'GET' | 'POST' | 'DELETE',
  path: string,
  body: JsonRequest | undefined,
  options: MailwerkOptions = {},
): Promise<T> {
  const { url, key, fetch: send } = settings(options);
  const signal = AbortSignal.timeout(options.timeoutMs ?? 15_000);
  let response: Response;
  let text: string;

  try {
    const headers: Record<string, string> = {};
    headers.authorization = `Bearer ${key}`;
    const request: RequestInit = { method, signal, headers };

    if (body !== undefined) {
      headers['content-type'] = 'application/json';
      request.body = JSON.stringify(body);
    }

    response = await send(url + path, request);
    text = await response.text();
  } catch (error) {
    if (signal.aborted)
      throw new MailwerkError('unavailable', 'Mailwerk request timed out; outcome is unknown', 504);
    throw error;
  }

  const parsed: JsonValue = text ? JSON.parse(text) : {};

  if (!response.ok) {
    // SAFETY: The v1 API error contract is an optional error envelope on every non-success response.
    const error = (parsed as { error?: { code?: string; message?: string } }).error;

    throw new MailwerkError(
      error?.code ?? 'unavailable',
      error?.message ?? `Mailwerk answered ${response.status}`,
      response.status,
    );
  }

  // SAFETY: Each generated operation binds T to its owned Mailwerk v1 endpoint response contract.
  return parsed as T;
}

export type Properties = Record<string, string | number | boolean | null>;

export interface Contact {
  id: string;
  externalId: string;
  properties: Properties;
  createdAt: string;
  updatedAt: string;
  erasedAt: string | null;
}

/** Create or update a contact. Never creates consent. */
export function contact(
  input: { externalId: string; email: string; properties?: Properties; restoreErased?: boolean },
  options?: MailwerkOptions,
): Promise<Contact> {
  return call('POST', '/v1/contacts', input, options);
}

/**
 * Start a double opt-in. Mailwerk sends the confirmation email and hosts the
 * confirmation page; nothing is subscribed until the reader clicks it.
 * `noticeText` is the exact wording shown next to your opt-in control — it is
 * stored with the consent record as the proof of what was agreed to.
 */
export function consentRequest(
  input: {
    externalId: string;
    email: string;
    purposes: string[];
    noticeVersion: string;
    noticeText: string;
    source: string;
    properties?: Properties;
  },
  options?: MailwerkOptions,
): Promise<{
  contactId: string;
  requestId: string;
  status: 'sent' | 'already_confirmed' | 'suppressed' | 'failed';
  alreadyConfirmed: string[];
}> {
  return call('POST', '/v1/consent/request', input, options);
}

/**
 * What this contact currently consents to, per purpose, with the date, the
 * source and the exact wording they were shown. This is what a preference page
 * renders from — keep no second copy of it in your own database.
 *
 * Throws `not_found` when the contact does not exist yet.
 */
export function consentGet(
  externalId: string,
  options?: MailwerkOptions,
): Promise<{
  contactId: string;
  consent: {
    purpose: string;
    state: 'confirmed' | 'withdrawn';
    at: string;
    source: string;
    noticeVersion: string | null;
    noticeText: string | null;
  }[];
}> {
  return call('GET', `/v1/consent/${encodeURIComponent(externalId)}`, undefined, options);
}

/**
 * Whether an address may be mailed at all. A preference page asks this before
 * offering signup, so someone whose address bounced is told to use another one
 * instead of pressing a button that silently does nothing.
 */
export function suppressionCheck(
  email: string,
  options?: MailwerkOptions,
): Promise<{ suppressed: boolean; reason?: string; at?: string }> {
  return call(
    'GET',
    `/v1/suppressions/check?email=${encodeURIComponent(email)}`,
    undefined,
    options,
  );
}

/** Narrow a contact to a subset of the purposes it already confirmed. */
export function consentUpdate(
  input: { externalId: string; purposes: string[]; source?: string },
  options?: MailwerkOptions,
): Promise<{ confirmed: string[]; withdrawn: string[] }> {
  return call('POST', '/v1/consent/update', input, options);
}

/** Post a product event. Idempotent by `id`; lifecycles trigger and exit on it. */
export function event(
  input: {
    id: string;
    externalId: string;
    name: string;
    properties?: Properties;
    contactProperties?: Properties;
    at?: string;
  },
  options?: MailwerkOptions,
): Promise<{
  status: 'recorded' | 'duplicate';
  id: string;
  contactId: string | null;
  enrolled: string[];
  exited: string[];
}> {
  return call('POST', '/v1/events', input, options);
}

/** Send one transactional message by template key. */
export function send(
  input: {
    template: string;
    externalId: string;
    /** Exact service-email destination; leaves existing profile and consent unchanged. */
    email?: string;
    variables?: Record<string, string | number>;
    idempotencyKey?: string;
  },
  options?: MailwerkOptions,
): Promise<{
  messageId: string;
  status: 'sent' | 'duplicate' | 'failed' | 'unknown';
  reason?: string;
}> {
  return call('POST', '/v1/send', input, options);
}

export interface MessageStatus {
  messageId: string;
  /** sent means provider acceptance, not inbox placement. */
  status: 'sent' | 'failed' | 'unknown';
  delivery: 'unconfirmed' | 'delivered' | 'bounced' | 'complained' | 'rejected' | 'delayed';
  claimedAt: string;
  acceptedAt: string | null;
  events: { type: string; at: string }[];
  reason: string | null;
  retry: 'do_not_resend' | 'correct_cause_then_new_request';
}

/** One request owns recipient upsert and sending. A deleted lifecycle never revives. */
export function transactional(
  input: {
    template: string;
    externalId: string;
    email: string;
    requestId: string;
    variables?: Record<string, string>;
    replyTo?: string;
  },
  options?: MailwerkOptions,
): Promise<MessageStatus & { replayed: boolean }> {
  return call('POST', '/v1/transactional', input, options);
}

/** Dedicated stock bridge keys only. Preserve this identity on uncertain outcomes. */
export function stockSubmission(
  input: {
    requestId: string;
    externalId: string;
    class: string;
    variant: 'default' | 'comment' | 'mention';
    email: string;
    html: string;
    text?: string;
  },
  options?: MailwerkOptions,
): Promise<MessageStatus & { replayed: boolean }> {
  return call('POST', '/v1/submissions', input, { timeoutMs: 10_000, ...options });
}

/** Inspect an uncertain request; this never sends an email. */
export function message(requestId: string, options?: MailwerkOptions): Promise<MessageStatus> {
  return call('GET', `/v1/messages/request/${encodeURIComponent(requestId)}`, undefined, options);
}

/** A lead key can send only to the immutable activated owner policy. */
export function lead(
  input: {
    template: string;
    requestId: string;
    replyTo: string;
    variables?: Record<string, string>;
  },
  options?: MailwerkOptions,
): Promise<MessageStatus & { replayed: boolean }> {
  return call('POST', '/v1/leads', input, options);
}

/**
 * Erasure. Call this when the account is deleted: the address and properties
 * are destroyed and running sequences are cancelled. The suppression entry
 * stays — it is the proof that sending stopped, and it holds no address.
 */
export function deleteContact(
  externalId: string,
  options?: MailwerkOptions & { fenceMissing?: boolean },
): Promise<{ erased: boolean; contactId: string }> {
  const query = options?.fenceMissing === true ? '?fenceMissing=true' : '';

  return call(
    'DELETE',
    `/v1/contacts/${encodeURIComponent(externalId)}${query}`,
    undefined,
    options,
  );
}

/** Complete scoped recipient export for the product's ordinary account export. */
export function exportContact(externalId: string, options?: MailwerkOptions): Promise<JsonValue> {
  return call('GET', `/v1/contacts/${encodeURIComponent(externalId)}/export`, undefined, options);
}

/** Active sequences, so you can reconcile the exits your webhooks missed. */
export function enrollments(
  query: { lifecycle?: string; state?: string; externalId?: string } = {},
  options?: MailwerkOptions,
): Promise<{
  enrollments: {
    id: string;
    lifecycle: string;
    externalId: string;
    state: string;
    dueAt: string | null;
  }[];
}> {
  const search = new URLSearchParams(
    Object.entries(query).filter((entry): entry is [string, string] => entry[1] !== undefined),
  );

  return call('GET', `/v1/enrollments${search.size ? `?${search}` : ''}`, undefined, options);
}

export interface ProjectMetrics {
  project: string;
  window: string;
  since: string;
  messages: { sent: number; failed: number; claimed: number };
  /**
   * Every event type seen in the window, including `unsubscribe_header` and
   * `unsubscribe_link` — that pair is "unsubscribes by path".
   */
  events: Record<string, number>;
  rates: { delivered: number | null; bounced: number | null; complained: number | null };
  doi: { requested: number; confirmed: number; expired: number };
  audience: { purpose: string; contacts: number }[];
  suppressions: { reason: string; count: number }[];
  campaigns: { id: string; name: string; state: string; accepted: number; failed: number }[];
  lifecycles: { id: string; name: string; active: number; due: number }[];
  /**
   * Work that was claimed and whose outcome is unknown. Nothing retries these;
   * they exist so a human can see a send that may or may not have happened.
   */
  stuck: { claimed_older_than_1h: number; enrollments_claimed_older_than_1h: number };
  generatedAt: string;
}

/** Counts, rates and audience sizes for this project. */
export function metrics(window = '7d', options?: MailwerkOptions): Promise<ProjectMetrics> {
  return call('GET', `/v1/metrics?window=${encodeURIComponent(window)}`, undefined, options);
}

/**
 * Verifies the URL, the key and the version this file was generated against.
 * Call it from a health check or a deploy step — a wrong key fails here rather
 * than at the first signup.
 */
export async function doctor(options?: MailwerkOptions): Promise<{
  ok: boolean;
  project: string;
  service: string;
  clientVersion: string;
}> {
  const status = await call<{ version?: string }>('GET', '/status', undefined, options);

  const authenticated = await metrics('1d', options);

  if (authenticated.project !== MAILWERK_PROJECT)
    throw new MailwerkError('forbidden', 'This key belongs to a different project', 403);

  return {
    ok: true,
    project: authenticated.project,
    service: status.version ?? 'unknown',
    clientVersion: MAILWERK_CLIENT_VERSION,
  };
}
